import sys
from math import gcd

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])

    if k > n // 2:
        print(-1)
        return

    result = []
    current_sum = 0

    for i in range(1, n + 1):
        if current_sum + i <= k:
            result.append(i)
            current_sum += i
        else:
            result.append(k - current_sum + i)
            break

    if len(result) < n:
        for i in range(len(result) + 1, n + 1):
            result.append(i)

    print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
